    if(args.Length==1&&args[0]=="pointer-rename"){string root=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(C.Self),"pointer-fixture-"+Guid.NewGuid().ToString("N"));System.IO.Directory.CreateDirectory(root);try{var acl=new System.Security.AccessControl.DirectorySecurity();acl.SetOwner(new System.Security.Principal.SecurityIdentifier(C.Sid));acl.SetAccessRuleProtection(true,false);acl.AddAccessRule(new System.Security.AccessControl.FileSystemAccessRule(new System.Security.Principal.SecurityIdentifier(C.Sid),System.Security.AccessControl.FileSystemRights.FullControl,System.Security.AccessControl.InheritanceFlags.ContainerInherit|System.Security.AccessControl.InheritanceFlags.ObjectInherit,System.Security.AccessControl.PropagationFlags.None,System.Security.AccessControl.AccessControlType.Allow));System.IO.Directory.SetAccessControl(root,acl);byte[] a=C.Utf8.GetBytes("first"),b=C.Utf8.GetBytes("second");using(var pin=new HubSshMaintenancePointer(root,C.Fingerprint(root))){pin.Create("pointer.new",a);pin.Rename("pointer.new","pointer.json",false,C.Hash(a));C.Require(C.Utf8.GetString(pin.ReadOptional("pointer.json",65536))=="first","POINTER_FIXTURE_BAD_CREATE");pin.Create("pointer.new",b);pin.Publish("pointer.new","pointer.json",C.Hash(b),C.Hash(a),"pointer.old",null);C.Require(C.Utf8.GetString(pin.ReadOptional("pointer.json",65536))=="second","POINTER_FIXTURE_BAD_REPLACE");C.Require(C.Utf8.GetString(pin.ReadOptional("pointer.old",65536))=="first","POINTER_FIXTURE_BACKUP_CHANGED");pin.Delete("pointer.old",C.Hash(a));pin.Delete("pointer.json",C.Hash(b));C.Require(pin.ReadOptional("pointer.json",65536)==null,"POINTER_FIXTURE_BAD_DELETE");pin.Verify();}Console.WriteLine(C.Canon(new Dictionary<string,object>{{"ok",true},{"scenario","pointer-rename"},{"rejected",false}}));return 0;}finally{foreach(string name in new string[]{"pointer.new","pointer.json","pointer.old"}){string path=System.IO.Path.Combine(root,name);if(System.IO.File.Exists(path))System.IO.File.Delete(path);}System.IO.Directory.Delete(root);}}
    if(args.Length==0){var req=HubSshMaintenanceEntry.Request();var m=req["manifest"] as Dictionary<string,object>;HubSshMaintenanceProcess.Accept(m,C.Num(req,"ordinal",1,2));Console.WriteLine(C.Canon(C.Result("capability-accepted")));return 0;}
    C.Require(args.Length==1,"FIXTURE_ARGUMENTS");string scenario=args[0];var manifest=Manifest();var received=new Dictionary<string,object>(manifest);HubSshMaintenanceProcess.Result result=null;
